import{_ as e,c as o,o as i,a3 as s}from"./chunks/framework.CoV49S2T.js";const m=JSON.parse('{"title":"Política de privacidad","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/privacy.md","filePath":"es/guide/privacy.md","lastUpdated":1786595765000}'),r={name:"es/guide/privacy.md"};function n(l,a,c,t,d,p){return i(),o("div",null,[...a[0]||(a[0]=[s('<h1 id="politica-de-privacidad" tabindex="-1">Política de privacidad <a class="header-anchor" href="#politica-de-privacidad" aria-label="Permalink to &quot;Política de privacidad&quot;">​</a></h1><p>ClipboardxAI es un gestor de portapapeles inteligente para macOS. Su privacidad es nuestra prioridad.</p><h2 id="diseno-local-primero" tabindex="-1">Diseño local-primero <a class="header-anchor" href="#diseno-local-primero" aria-label="Permalink to &quot;Diseño local-primero&quot;">​</a></h2><ul><li>Su historial del portapapeles se almacena completamente en su Mac.</li><li>Las acciones locales integradas (extraer enlaces, contar estadísticas, colapsar líneas en blanco y sugerencias de ML en el dispositivo) se ejecutan totalmente sin conexión.</li><li>No se requiere cuenta ni registro para usar la aplicación principal.</li><li>No se requiere conexión a internet para la gestión local del portapapeles ni para las funciones en el dispositivo.</li></ul><h2 id="ia-en-la-nube-opcional" tabindex="-1">IA en la nube (opcional) <a class="header-anchor" href="#ia-en-la-nube-opcional" aria-label="Permalink to &quot;IA en la nube (opcional)&quot;">​</a></h2><p>ClipboardxAI puede usar opcionalmente proveedores de IA en la nube (como DeepSeek, MiniMax, GLM, Kimi, Mistral o un servidor Ollama local) para potenciar acciones avanzadas como resumir, traducir y avisos personalizados.</p><ul><li>Cuando se activa, el texto seleccionado o el contenido del portapapeles se envía <strong>directamente al proveedor que configure</strong>, usando <strong>su propia API key</strong>.</li><li>Su API key solo se almacena en el Keychain de su Mac y nunca se nos sube.</li><li>Puede desactivar la IA en la nube en cualquier momento y seguir usando las funciones locales.</li><li>El historial del portapapeles <strong>no</strong> se envía a la nube automáticamente; las solicitudes en la nube solo se activan cuando ejecuta una acción en la nube.</li></ul><h2 id="lo-que-no-recopilamos" tabindex="-1">Lo que no recopilamos <a class="header-anchor" href="#lo-que-no-recopilamos" aria-label="Permalink to &quot;Lo que no recopilamos&quot;">​</a></h2><ul><li>No recopilamos el contenido de su portapapeles, documentos ni archivos.</li><li>No rastreamos su actividad, comportamiento de navegación ni patrones de uso.</li><li>No operamos ningún servidor que reciba sus datos del portapapeles.</li><li>No incluimos SDK de analítica, publicidad o seguimiento de terceros.</li><li>No tenemos ningún sistema de telemetría.</li></ul><h2 id="que-datos-se-almacenan-localmente" tabindex="-1">Qué datos se almacenan localmente <a class="header-anchor" href="#que-datos-se-almacenan-localmente" aria-label="Permalink to &quot;Qué datos se almacenan localmente&quot;">​</a></h2><p>Los siguientes datos se almacenan solo en su dispositivo:</p><ul><li><strong>Historial del portapapeles</strong>: elementos recientes para acceso rápido (guardados en su Mac).</li><li><strong>Ajustes de la aplicación</strong>: tema, preferencia de idioma, acciones activadas, configuración del proveedor.</li><li><strong>API keys</strong>: almacenadas de forma segura en el Keychain local (solo si configura un proveedor en la nube).</li><li><strong>Acciones personalizadas</strong>: avisos y configuración que cree.</li><li><strong>Registros</strong>: registros de depuración para la solución de problemas (pueden eliminarse en cualquier momento).</li></ul><h2 id="permisos-usados-por-la-aplicacion" tabindex="-1">Permisos usados por la aplicación <a class="header-anchor" href="#permisos-usados-por-la-aplicacion" aria-label="Permalink to &quot;Permisos usados por la aplicación&quot;">​</a></h2><ul><li><strong>Accesibilidad / Acceso total al disco</strong>: necesario para leer el portapapeles del sistema y ofrecer atajos globales.</li><li><strong>Notificaciones</strong>: opcional, para avisos de finalización en solicitudes en la nube de larga duración.</li></ul><p>Puede gestionar estos permisos en <strong>Configuración del sistema → Privacidad y seguridad</strong> en cualquier momento.</p><h2 id="compras-dentro-de-la-aplicacion-licencia" tabindex="-1">Compras dentro de la aplicación / Licencia <a class="header-anchor" href="#compras-dentro-de-la-aplicacion-licencia" aria-label="Permalink to &quot;Compras dentro de la aplicación / Licencia&quot;">​</a></h2><p>Las compras de licencia (si las hay) las procesa Apple a través de la Mac App Store. ClipboardxAI no recibe ni almacena su información de pago. Los recibos de licencia se almacenan localmente para verificar la titularidad.</p><h2 id="servicios-de-terceros" tabindex="-1">Servicios de terceros <a class="header-anchor" href="#servicios-de-terceros" aria-label="Permalink to &quot;Servicios de terceros&quot;">​</a></h2><p>ClipboardxAI en sí no incluye ningún servicio de analítica, publicidad o seguimiento de terceros. Cuando activa un proveedor de IA en la nube, sus solicitudes las gestiona ese proveedor bajo su propia política de privacidad.</p><h2 id="solicitudes-de-privacidad" tabindex="-1">Solicitudes de privacidad <a class="header-anchor" href="#solicitudes-de-privacidad" aria-label="Permalink to &quot;Solicitudes de privacidad&quot;">​</a></h2><p>Dado que ClipboardxAI almacena todos los datos localmente en su dispositivo, no conservamos ningún dato personal en nuestros servidores. Si tiene preguntas sobre la privacidad, póngase en contacto con nosotros.</p><h2 id="contacto" tabindex="-1">Contacto <a class="header-anchor" href="#contacto" aria-label="Permalink to &quot;Contacto&quot;">​</a></h2><p>Para preguntas sobre privacidad, abra un issue en <a href="https://github.com/clipboardxAI/clipboard-site/issues" target="_blank" rel="noreferrer">GitHub Issues</a> o envíenos un correo a <a href="mailto:clipboardxai@w3cub.com" target="_blank" rel="noreferrer">clipboardxai@w3cub.com</a>.</p>',23)])])}const g=e(r,[["render",n]]);export{m as __pageData,g as default};
